import ifcopenshell, numpy as np
import ifcopenshell.util.placement as up
f=ifcopenshell.open("15_model/DC2-A-STR_Roof_Structure_Model_RevC.ifc")
def info(el):
    m=up.get_local_placement(el.ObjectPlacement)
    # find extruded area solid
    reps=el.Representation.Representations
    for r in reps:
        for it in r.Items:
            if it.is_a("IfcExtrudedAreaSolid"):
                prof=it.SweptArea
                if prof.is_a("IfcRectangleProfileDef"):
                    dims=(prof.XDim,prof.YDim)
                else:
                    pts=[(p.Coordinates[0],p.Coordinates[1]) for p in prof.OuterCurve.Points]
                    dims=pts
                return m[:3,3]/304.8, (m[0,3]/304.8,m[1,3]/304.8), dims, it.Depth
for el in f.by_type("IfcBuildingElementProxy")+f.by_type("IfcWall")+f.by_type("IfcOpeningElement"):
    loc,xy,dims,depth=info(el)
    print(f"{el.Name:14s} origin=({loc[0]:7.2f},{loc[1]:7.2f}) dims={dims} depth_ft={depth/304.8:.2f}")
