from fe import *
import numpy as np
Fpx=195.43; Wtot=118.0; Wtoty=152.0
def allscen(gp):
    K,panels,springs=build(lambda x,y: gp)
    res={}
    for name,F in [('S05',load_wall(Wtot,'X')),('S05b',load_wall(Wtot,'X',0.75,0.15*180)),
        ('S06',load_wall(Wtoty,'Y')),('S06b',load_wall(Wtoty,'Y',0.75,0.15*240)),
        ('S07',load_seismic(Fpx,'X',0.05*180)),('S08',load_seismic(Fpx,'Y',0.05*240))]:
        u=solve(K,F); res[name]=results(u,panels,springs,F)
    return res
for gp in (10.1,17.5,20.8):
    res=allscen(gp)
    m={}
    for s,r in res.items():
        for (i,j,qx,qy,q) in r['panels']:
            m[(i,j)]=max(m.get((i,j),0),q*1000)
    print('=== G',gp,'max',max(m.values()))
    # histogram
    import collections
    for thr in (285,400,496,585,694,743,819,905,1040):
        print('   >%4d : %3d panels  %6d sf'%(thr,sum(1 for v in m.values() if v>thr),sum(1 for v in m.values() if v>thr)*180))
    print('   shear map rows (j=29..0, i step 2) kip/ft*1000')
    print('     '+''.join(f'{i:5d}' for i in range(0,40,2)))
    for j in range(29,-1,-1):
        row=''
        for i in range(0,40,2):
            v=m.get((i,j)); row += '    .' if v is None else f'{v:5.0f}'
        print(f'{j:3d}  '+row)
