import numpy as np, math, collections
from design import Design, SPECS, spec_props, spec_rate
import model as M
from fe import build, solve, load_seismic, load_wall, results

Fpx=195.43; WIND_X=118.0; WIND_Y=152.0
def make_design(rects):
    R=[]
    for k,(i0,i1,j0,j1,spec) in enumerate(rects):
        R.append(dict(zone=spec, x0=i0*6.0,y0=j0*6.0,x1=i1*6.0,y1=j1*6.0,spec=spec))
    return Design(R)

def evaluate(rects, verbose=False):
    d=make_design(rects)
    r=d.run(); m=d.panel_demand()
    viol=[]
    for (i,j),q in m.items():
        x0,x1=i*6,(i+1)*6; y0,y1=j*30,(j+1)*30
        caps=[]
        for rr in d.rects:
            if min(x1,rr['x1'])-max(x0,rr['x0'])>1e-9 and min(y1,rr['y1'])-max(y0,rr['y0'])>1e-9:
                caps.append((spec_props(rr['spec'])['cap'],rr['spec'],rr['zone']))
        cap=min(caps)
        if q > 0.95*cap[0]: viol.append(((i,j),round(q),cap))
    dist={s:r[s]['distortion'] for s in r}
    chord={s:r[s]['chord_max'] for s in r}
    coll={s:max(r[s]['coll_max']['X'],r[s]['coll_max']['Y']) for s in r}
    return dict(d=d,res=r,pm=m,viol=viol,dist=dist,chord=chord,coll=coll)

def report(rects,tag=''):
